  "bodyHtml": "<p class=\"hw-prompt\">Before adjustment, utilities expense has a balance of $39,000. The company estimates an additional $3,800 of utilities have been used but not yet billed. What should adjusted utilities expense equal?</p>\n      <select data-correct=\"$42,800\"><option value=\"\">-- select --</option><option>$35,200</option><option>$39,000</option><option>$42,800</option><option>$46,600</option></select>",
